15	/**
16	 * 将领域业务异常映射为约定的 HTTP 状态码与错误体。
17	 */
18	@RestControllerAdvice
19	public class ApiExceptionHandler {
20	
21	    @ExceptionHandler(NotFoundException.class)
22	    public ResponseEntity<ErrorResponse> handleNotFound(NotFoundException ex) {
23	        return build(HttpStatus.NOT_FOUND, "NOT_FOUND", ex.getMessage());
24	    }
25	
26	    @ExceptionHandler(ConflictException.class)
27	    public ResponseEntity<ErrorResponse> handleConflict(ConflictException ex) {
28	        return build(HttpStatus.CONFLICT, "CONFLICT", ex.getMessage());
29	    }
30	
31	    @ExceptionHandler(BadRequestException.class)
32	    public ResponseEntity<ErrorResponse> handleBadRequest(BadRequestException ex) {
33	        return build(HttpStatus.BAD_REQUEST, "BAD_REQUEST", ex.getMessage());
34	    }
35	
36	    @ExceptionHandler(UnprocessableEntityException.class)
37	    public ResponseEntity<ErrorResponse> handleUnprocessable(UnprocessableEntityException ex) {
38	        return build(HttpStatus.UNPROCESSABLE_ENTITY, "UNPROCESSABLE_ENTITY", ex.getMessage());
39	    }
40	
41	    @ExceptionHandler(MethodArgumentNotValidException.class)
42	    public ResponseEntity<ErrorResponse> handleValidation(MethodArgumentNotValidException ex) {
43	        String message = ex.getBindingResult().getFieldErrors().stream()
44	                .map(error -> error.getField() + " " + error.getDefaultMessage())
45	                .findFirst()
46	                .orElse("请求参数校验失败");
47	        return build(HttpStatus.BAD_REQUEST, "BAD_REQUEST", message);
48	    }
49	
50	    @ExceptionHandler(HttpMessageNotReadableException.class)
51	    public ResponseEntity<ErrorResponse> handleUnreadable(HttpMessageNotReadableException ex) {
52	        return build(HttpStatus.BAD_REQUEST, "BAD_REQUEST", "请求体无法解析");
53	    }
54	
55	    @ExceptionHandler(DuplicateKeyException.class)
56	    public ResponseEntity<ErrorResponse> handleDuplicateKey(DuplicateKeyException ex) {
57	        return build(HttpStatus.CONFLICT, "CONFLICT", "唯一键冲突");
58	    }
59	
60	    private ResponseEntity<ErrorResponse> build(HttpStatus status, String error, String message) {
61	        return ResponseEntity.status(status).body(new ErrorResponse(error, message));
62	    }
