package com.example.starter.race.api;

import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

/**
 * 配置赛事器材检录请求（仅 OPEN 赛事可配置，可重复配置；历史 PASS 按提交时快照计算有效期）。
 *
 * @param mandatory       是否强制检录：true 时起跑/首个分段计时前须有未过期 PASS
 * @param validMinutes    检录 PASS 有效分钟数，取值 1~1440
 * @param expectedVersion 客户端所见赛事版本
 * @param requestId       全局唯一请求ID（幂等键）
 */
public record ConfigureInspectionRequest(
        @NotNull Boolean mandatory,
        @NotNull @Min(1) @Max(1440) Integer validMinutes,
        @NotNull Integer expectedVersion,
        @NotBlank String requestId
) {
}

package com.example.starter.race.api;

/**
 * 赛事器材检录配置响应。
 *
 * @param raceId       赛事ID
 * @param version      配置成功后的赛事版本号
 * @param mandatory    是否强制检录
 * @param validMinutes 检录 PASS 有效分钟数（1~1440）
 * @param createdAt    首次配置时间，Unix毫秒时间戳
 * @param updatedAt    最近配置时间，Unix毫秒时间戳
 */
public record InspectionConfigResponse(
        String raceId,
        int version,
        boolean mandatory,
        int validMinutes,
        long createdAt,
        long updatedAt
) {
}

package com.example.starter.race.api;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;

/**
 * 选手提交器材检录请求（复检也使用本接口，每次新插不可变历史记录）。
 *
 * @param inspectionKey   检录记录ID，全局唯一（兼作幂等键；同键同参重放，异参409）
 * @param equipmentSerial 器材序列号，赛事内同一序列号同一时刻仅可绑定一名未完赛选手
 * @param result          检录结果，仅允许 PASS 或 FAIL
 * @param expectedVersion 客户端所见赛事版本
 * @param requestId       全局唯一请求ID（幂等键）
 */
public record SubmitInspectionRequest(
        @NotBlank String inspectionKey,
        @NotBlank String equipmentSerial,
        @NotBlank @Pattern(regexp = "PASS|FAIL") String result,
        @NotNull Integer expectedVersion,
        @NotBlank String requestId
) {
}

package com.example.starter.race.api;

import com.fasterxml.jackson.annotation.JsonInclude;

/**
 * 单条器材检录历史记录响应（记录不可变）。
 *
 * @param inspectionId    检录记录ID（inspectionKey）
 * @param bib             选手参赛号
 * @param equipmentSerial 器材序列号
 * @param result          检录结果 PASS / FAIL
 * @param validMinutes    提交时配置的有效分钟数快照
 * @param inspectedAt     检录提交时刻，Unix毫秒时间戳
 * @param validUntil      PASS 有效期截止时刻（含端点）；FAIL 为 null
 */
@JsonInclude(JsonInclude.Include.NON_NULL)
public record InspectionRecordResponse(
        String inspectionId,
        String bib,
        String equipmentSerial,
        String result,
        int validMinutes,
        long inspectedAt,
        Long validUntil
) {
}

