}

package com.example.starter.race.api;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

/**
 * 选手退赛请求；退赛为终态并释放其器材绑定。
 *
 * @param reason          退赛原因，可空，最长256字符
 * @param expectedVersion 客户端所见赛事版本
 * @param requestId       全局唯一请求ID（幂等键）
 */
public record WithdrawRunnerRequest(
        @Size(max = 256) String reason,
        @NotNull Integer expectedVersion,
        @NotBlank String requestId
) {
}

package com.example.starter.race.api;

import com.fasterxml.jackson.annotation.JsonInclude;

/**
 * 选手起跑/退赛状态响应。
 *
 * @param raceId      赛事ID
 * @param bib         参赛号
 * @param state       状态：REGISTERED-未起跑，STARTED-已起跑，WITHDRAWN-已退赛
 * @param startedAt   起跑时间，Unix毫秒时间戳；未起跑为 null
 * @param withdrawnAt 退赛时间，Unix毫秒时间戳；未退赛为 null
 * @param reason      退赛原因；未退赛为 null
 * @param updatedAt   最近状态变更时间，Unix毫秒时间戳
 */
@JsonInclude(JsonInclude.Include.NON_NULL)
public record RunnerRaceStateResponse(
        String raceId,
        String bib,
        String state,
        Long startedAt,
        Long withdrawnAt,
        String reason,
        long updatedAt
) {
}

package com.example.starter.race.api;

import com.fasterxml.jackson.annotation.JsonInclude;

/**
 * 选手当前器材检录有效状态查询响应。
 *
 * @param raceId       赛事ID
 * @param bib          参赛号
 * @param mandatory    赛事是否强制检录；false 时 effective 恒为 NOT_REQUIRED
 * @param effective    当前有效性：PASS_VALID-未过期PASS可起跑，FAIL-最近结果FAIL，
 *                     EXPIRED-最近PASS已过期，NONE-从无检录记录，NOT_REQUIRED-非强制赛事
 * @param latest       最近一条检录记录；从无检录时为 null
 * @param nowMillis    服务端当前时刻，Unix毫秒时间戳（可注入时钟）
 */
@JsonInclude(JsonInclude.Include.NON_NULL)
public record InspectionStatusResponse(
        String raceId,
        String bib,
        boolean mandatory,
        String effective,
        InspectionRecordResponse latest,
        long nowMillis
) {
}

