    }

    @Test
    void 同requestId并发检录重放只产生一条记录() throws Exception {
        seed();
        int threads = 6;
        ExecutorService pool = Executors.newFixedThreadPool(threads);
        CountDownLatch start = new CountDownLatch(1);
        AtomicInteger ok = new AtomicInteger();
